  const chatParam = String(route.query.chat || '').trim()
  if (!runParam && !chatParam) return null
  const direct = runs.value.find(
    item =>
      item.run_id === runParam ||
      item.run_id === chatParam ||
      item.main_chat_id === runParam ||
      item.main_chat_id === chatParam
  )
