  refresh()
  loadAudit()
  refreshTimer = setInterval(() => {
    if (!live.value) return
    refresh()
    loadAudit(true)
  }, 10000)
})

onUnmounted(() => {
  if (refreshTimer) clearInterval(refreshTimer)
})
