        const created = await $storex.chats.importChat(chat)
        if (created) imported.push({ source: sourceChat, chat: created })
      }

      // 4. Link the kanban tasks into their columns (sprint uses `sprints`).
      if (boardType !== 'sprint') {
        linkChatsToColumns(board, imported)
